#!/usr/bin/env bash
set -Eeuo pipefail

SID="${1:-25}"
STAMP="$(date +%Y%m%d-%H%M%S)"
BACKUP="/root/oldz-core-fix-v3-${SID}-${STAMP}"

echo "================================================================"
echo " OLD ZOMBIE CORE FIX v3"
echo " Server: #${SID}"
echo " Backup: ${BACKUP}"
echo " Fixes: FastDL BSP / YaPB toggle / Knife menu"
echo "================================================================"

if [[ "${EUID}" -ne 0 ]]; then
  echo "[ERROR] Run as root."
  exit 1
fi

mkdir -p "$BACKUP"

CFG="/var/lib/hyper-cs16/servers/${SID}.json"
LEGACY_CFG="/etc/hyper-cs16/servers/${SID}.json"

read_json_value() {
  local file="$1" key="$2"
  python3 - "$file" "$key" <<'PY'
import json,sys
try:
    d=json.load(open(sys.argv[1],encoding='utf-8'))
    v=d.get(sys.argv[2],"")
    print(v if v is not None else "")
except Exception:
    print("")
PY
}

SERVER_ROOT=""
if [[ -f "$CFG" ]]; then
  SERVER_ROOT="$(read_json_value "$CFG" path)"
elif [[ -f "$LEGACY_CFG" ]]; then
  SERVER_ROOT="$(read_json_value "$LEGACY_CFG" path)"
fi
[[ -n "$SERVER_ROOT" ]] || SERVER_ROOT="/srv/hyper-cs16/servers/${SID}"

CSTRIKE="${SERVER_ROOT}/cstrike"
if [[ ! -d "$CSTRIKE" ]]; then
  echo "[ERROR] cstrike not found: $CSTRIKE"
  exit 2
fi

PUBLIC_IP=""
if [[ -f /etc/hyper-cs16/runtime.json ]]; then
  PUBLIC_IP="$(read_json_value /etc/hyper-cs16/runtime.json public_ip)"
fi
if [[ -z "$PUBLIC_IP" && -f "$CFG" ]]; then
  PUBLIC_IP="$(read_json_value "$CFG" public_ip)"
fi
if [[ -z "$PUBLIC_IP" ]]; then
  PUBLIC_IP="$(hostname -I 2>/dev/null | awk '{print $1}')"
fi
if ! [[ "$PUBLIC_IP" =~ ^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$ ]]; then
  echo "[ERROR] Cannot determine public IPv4. Got: '$PUBLIC_IP'"
  exit 3
fi

echo "[INFO] Server root: $SERVER_ROOT"
echo "[INFO] Public IP:   $PUBLIC_IP"

mkdir -p "$BACKUP/cstrike" "$BACKUP/nginx" "$BACKUP/panel"

for f in \
  "$CSTRIKE/server.cfg" \
  "$CSTRIKE/addons/amxmodx/configs/plugins.ini" \
  "$CSTRIKE/addons/amxmodx/plugins/zm_addon_knife.amxx" \
  "$CSTRIKE/addons/amxmodx/scripting/zm_addon_knife.sma"
do
  if [[ -f "$f" ]]; then
    cp -a "$f" "$BACKUP/cstrike/$(echo "${f#$CSTRIKE/}" | tr '/' '_')"
  fi
done

if [[ -f /etc/nginx/conf.d/00-hyper-fastdl-ip.conf ]]; then
  cp -a /etc/nginx/conf.d/00-hyper-fastdl-ip.conf "$BACKUP/nginx/"
fi

echo
echo "[1/3] Fixing FastDL binary route..."

MAP="$CSTRIKE/maps/zm_2day.bsp"
if [[ ! -f "$MAP" ]]; then
  echo "[ERROR] Current map not found: $MAP"
  exit 10
fi

MAP_VER="$(python3 - "$MAP" <<'PY'
import struct,sys
with open(sys.argv[1],'rb') as f:
    b=f.read(4)
print(struct.unpack('<I',b)[0] if len(b)==4 else -1)
PY
)"
if [[ "$MAP_VER" != "30" ]]; then
  echo "[ERROR] SOURCE map is invalid: $MAP (version=$MAP_VER, expected=30)"
  exit 11
fi

FASTDL_ROOT="/srv/hyper-cs16/fastdl"
DEST="$FASTDL_ROOT/$SID"
mkdir -p "$DEST"

for d in maps models sound sprites gfx resource overviews events media; do
  if [[ -d "$CSTRIKE/$d" ]]; then
    mkdir -p "$DEST/$d"
    rsync -a --delete --safe-links "$CSTRIKE/$d/" "$DEST/$d/"
  fi
done

find "$DEST" -maxdepth 1 -type f -iname '*.wad' -delete 2>/dev/null || true
find "$CSTRIKE" -maxdepth 1 -type f -iname '*.wad' -exec cp -a {} "$DEST/" \;

chown -R root:www-data "$DEST" 2>/dev/null || true
find "$DEST" -type d -exec chmod 0755 {} +
find "$DEST" -type f -exec chmod 0644 {} +

FAST_MAP="$DEST/maps/zm_2day.bsp"
if [[ ! -f "$FAST_MAP" ]]; then
  echo "[ERROR] FastDL copy of zm_2day.bsp was not created."
  exit 12
fi

SRC_SHA="$(sha256sum "$MAP" | awk '{print $1}')"
DST_SHA="$(sha256sum "$FAST_MAP" | awk '{print $1}')"
if [[ "$SRC_SHA" != "$DST_SHA" ]]; then
  echo "[ERROR] FastDL BSP does not match source BSP."
  exit 13
fi

cat > /etc/nginx/conf.d/00-hyper-fastdl-ip.conf <<EOF
# HYPER-HOST / OLD ZOMBIE FastDL raw-binary endpoint
server {
    listen 80;
    server_name ${PUBLIC_IP};

    access_log /var/log/nginx/hyper-fastdl_access.log;
    error_log  /var/log/nginx/hyper-fastdl_error.log warn;

    location ^~ /fastdl/ {
        root /srv/hyper-cs16;
        try_files \$uri =404;
        default_type application/octet-stream;
        add_header X-Content-Type-Options nosniff always;
        add_header Cache-Control "public, max-age=31536000, immutable" always;
        sendfile on;
        tcp_nopush on;
    }

    location / {
        return 404;
    }
}
EOF

nginx -t
systemctl reload nginx

TMP_BSP="$(mktemp)"
trap 'rm -f "$TMP_BSP"' EXIT
curl -fsS --max-time 15 -H "Host: ${PUBLIC_IP}" \
  "http://127.0.0.1/fastdl/${SID}/maps/zm_2day.bsp" -o "$TMP_BSP"

HTTP_VER="$(python3 - "$TMP_BSP" <<'PY'
import struct,sys
with open(sys.argv[1],'rb') as f:
    b=f.read(4)
print(struct.unpack('<I',b)[0] if len(b)==4 else -1)
PY
)"
HTTP_SHA="$(sha256sum "$TMP_BSP" | awk '{print $1}')"

if [[ "$HTTP_VER" != "30" || "$HTTP_SHA" != "$SRC_SHA" ]]; then
  echo "[ERROR] nginx FastDL test failed."
  echo "        HTTP BSP version: $HTTP_VER"
  echo "        source sha256:    $SRC_SHA"
  echo "        HTTP sha256:      $HTTP_SHA"
  exit 14
fi

echo "[OK] FastDL HTTP returns real BSP v30, sha256 matches."

python3 - "$CSTRIKE/server.cfg" "$PUBLIC_IP" "$SID" <<'PY'
from pathlib import Path
import re,sys
p=Path(sys.argv[1]); ip=sys.argv[2]; sid=int(sys.argv[3])
text=p.read_text(encoding='utf-8',errors='ignore') if p.exists() else ''
text=text.replace('\r\n','\n').replace('\r','\n')
text=re.sub(r'(?ims)^\s*// HYPER-HOST FASTDL BEGIN\s*$.*?^\s*// HYPER-HOST FASTDL END\s*$\n?','',text)
managed={'sv_downloadurl','sv_allowdownload','sv_allowupload','sv_send_resources','sv_allow_dlfile'}
kept=[]
for line in text.splitlines():
    m=re.match(r'^\s*([A-Za-z_][A-Za-z0-9_]*)\s+',line)
    if m and m.group(1).lower() in managed:
        continue
    kept.append(line)
block=[
    '// HYPER-HOST FASTDL BEGIN',
    '// Raw binary FastDL endpoint.',
    'sv_allowdownload 1',
    'sv_allowupload 1',
    'sv_send_resources 1',
    'sv_allow_dlfile 1',
    f'sv_downloadurl "http://{ip}/fastdl/{sid}/"',
    '// HYPER-HOST FASTDL END',
]
p.write_text('\n'.join(kept).rstrip()+'\n\n'+'\n'.join(block)+'\n',encoding='utf-8')
PY

echo
echo "[2/3] Restoring knife selection..."

AMXX_DIR="$CSTRIKE/addons/amxmodx"
mkdir -p "$AMXX_DIR/plugins" "$AMXX_DIR/scripting" "$AMXX_DIR/configs"

cat > /tmp/oldz_knife.amxx.b64 <<'B64AMXX'

B64AMXX
base64 -d /tmp/oldz_knife.amxx.b64 > "$AMXX_DIR/plugins/zm_addon_knife.amxx"
rm -f /tmp/oldz_knife.amxx.b64

cat > /tmp/oldz_knife.sma.b64 <<'B64SMA'

B64SMA
base64 -d /tmp/oldz_knife.sma.b64 > "$AMXX_DIR/scripting/zm_addon_knife.sma"
rm -f /tmp/oldz_knife.sma.b64

chmod 0644 "$AMXX_DIR/plugins/zm_addon_knife.amxx" "$AMXX_DIR/scripting/zm_addon_knife.sma"
chown cs16:www-data "$AMXX_DIR/plugins/zm_addon_knife.amxx" "$AMXX_DIR/scripting/zm_addon_knife.sma" 2>/dev/null || true

PLUGINS="$AMXX_DIR/configs/plugins.ini"
[[ -f "$PLUGINS" ]] || touch "$PLUGINS"

python3 - "$PLUGINS" <<'PY'
from pathlib import Path
import sys
p=Path(sys.argv[1])
lines=p.read_text(encoding='utf-8',errors='ignore').splitlines()
out=[]; seen=False
for line in lines:
    stripped=line.strip()
    token=stripped.lstrip(';').strip().split(None,1)[0].lower() if stripped else ''
    if token=='zm_addon_knife_r8.amxx':
        out.append('; zm_addon_knife_r8.amxx ; OLD duplicate disabled')
        continue
    if token=='zm_addon_knife.amxx':
        if not seen:
            out.append('zm_addon_knife.amxx')
            seen=True
        continue
    out.append(line)
if not seen:
    idx=next((i+1 for i,x in enumerate(out) if x.strip().lower()=='zmpl.amxx'),len(out))
    out.insert(idx,'zm_addon_knife.amxx')
p.write_text('\n'.join(out).rstrip()+'\n',encoding='utf-8')
PY

ZMPL_SMA="$AMXX_DIR/scripting/zmpl.sma"
AMXXPC="$AMXX_DIR/scripting/amxxpc"
if [[ -f "$ZMPL_SMA" ]] && grep -q 'client_cmd(id, "knife_zb")' "$ZMPL_SMA"; then
  echo "[INFO] zmpl.sma contains automatic knife-menu call."
  if [[ -x "$AMXXPC" ]]; then
    TMP_AMXX="/tmp/zmpl.${SID}.amxx"
    if "$AMXXPC" "$ZMPL_SMA" "-o${TMP_AMXX}" >/tmp/zmpl-compile.log 2>&1; then
      cp -a "$TMP_AMXX" "$AMXX_DIR/plugins/zmpl.amxx"
      chown cs16:www-data "$AMXX_DIR/plugins/zmpl.amxx" 2>/dev/null || true
      chmod 0644 "$AMXX_DIR/plugins/zmpl.amxx"
      rm -f "$TMP_AMXX"
      echo "[OK] zmpl.amxx rebuilt with automatic knife menu."
    else
      echo "[WARN] zmpl compile failed; existing zmpl.amxx left untouched."
      tail -n 30 /tmp/zmpl-compile.log || true
    fi
  fi
else
  echo "[WARN] zmpl.sma has no automatic knife-menu call. /knife still works."
fi

echo
echo "[3/3] Fixing YaPB enable/disable..."

mapfile -t CTL_CANDIDATES < <(
  {
    printf '%s\n' \
      /opt/hyper-cs16/bin/hyper-cs16-ctl \
      /root/hyper-hosting-panel/cs16-panel/bin/hyper-cs16-ctl \
      /usr/local/bin/hyper-cs16-ctl \
      /usr/local/sbin/hyper-cs16-ctl
    find /opt/hyper-cs16 /root/hyper-hosting-panel -type f -name hyper-cs16-ctl 2>/dev/null || true
  } | awk 'NF && !seen[$0]++'
)

PATCHED_CTL=0
for CTL in "${CTL_CANDIDATES[@]}"; do
  [[ -f "$CTL" ]] || continue

  if ! grep -q '^def main()' "$CTL" 2>/dev/null || ! grep -q '^def install_yapb' "$CTL" 2>/dev/null; then
    echo "[SKIP] wrapper/non-Python controller: $CTL"
    continue
  fi

  echo "[PATCH] Python controller: $CTL"
  cp -a "$CTL" "$BACKUP/panel/$(echo "$CTL" | tr '/' '_').bak"

  python3 - "$CTL" <<'PY'
from pathlib import Path
import sys

p=Path(sys.argv[1])
s=p.read_text(encoding='utf-8')

helper="\n".join([
"def _set_yapb_metamod_enabled(cstrike:Path, enabled:bool):",
"    p=cstrike/'addons/metamod/plugins.ini'",
"    p.parent.mkdir(parents=True,exist_ok=True)",
"    lines=p.read_text(encoding='utf-8',errors='ignore').splitlines() if p.exists() else []",
"    needle='addons/yapb/bin/yapb.so'",
"    found=False; out_lines=[]",
"    for line in lines:",
"        if needle in line.lower():",
"            if found:",
"                continue",
"            found=True",
"            out_lines.append('linux addons/yapb/bin/yapb.so' if enabled else ';linux addons/yapb/bin/yapb.so')",
"        else:",
"            out_lines.append(line)",
"    if not found:",
"        out_lines.append('linux addons/yapb/bin/yapb.so' if enabled else ';linux addons/yapb/bin/yapb.so')",
"    p.write_text('\\\\n'.join(out_lines).rstrip()+'\\\\n',encoding='utf-8')",
"",
""
])
if 'def _set_yapb_metamod_enabled(' not in s:
    marker='def install_yapb(sid:int,quota:int=9,difficulty:int=3):'
    if marker not in s:
        raise SystemExit('install_yapb marker missing')
    s=s.replace(marker,helper+marker,1)

s=s.replace(
    "_append_unique(cstrike/'addons/metamod/plugins.ini','linux addons/yapb/bin/yapb.so')",
    "_set_yapb_metamod_enabled(cstrike,True)"
)

cfg_sig="def configure_yapb(sid:int,quota:int,difficulty:int):"
pos=s.find(cfg_sig)
if pos>=0:
    body_end=s.find('\ndef disable_yapb(',pos)
    body=s[pos:body_end if body_end>pos else len(s)]
    if "_set_yapb_metamod_enabled(path/'cstrike',True)" not in body:
        target="quota=max(0,min(31,int(quota))); difficulty=max(0,min(4,int(difficulty)))"
        body=body.replace(target,target+"\n    _set_yapb_metamod_enabled(path/'cstrike',True)",1)
        s=s[:pos]+body+s[body_end if body_end>pos else len(s):]

enable_fn="\n".join([
"def enable_yapb(sid:int,quota:int|None=None,difficulty:int|None=None):",
"    require_root(); c=load_server(sid); path=Path(c['path']); cstrike=path/'cstrike'",
"    ycfg=cstrike/'addons/yapb/conf/yapb.cfg'",
"    q=int(c.get('bots_quota',9) if quota is None else quota)",
"    d=int(c.get('bots_difficulty',3) if difficulty is None else difficulty)",
"    q=max(0,min(31,q)); d=max(0,min(4,d))",
"    if not ycfg.exists() or not (cstrike/'addons/yapb').is_dir():",
"        return install_yapb(sid,q,d)",
"    _set_yapb_metamod_enabled(cstrike,True)",
"    _set_cfg_cvar(ycfg,'yb_quota',str(q))",
"    _set_cfg_cvar(ycfg,'yb_quota_mode','fill')",
"    _set_cfg_cvar(ycfg,'yb_difficulty',str(d))",
"    _set_cfg_cvar(ycfg,'yb_autovacate','1')",
"    _set_cfg_cvar(ycfg,'yb_autovacate_keep_slots','1')",
"    _set_cfg_cvar(ycfg,'yb_language','ru')",
"    normalize_permissions(path)",
"    c['bots_enabled']=1; c['bots_quota']=q; c['bots_difficulty']=d",
"    save_server(c)",
"    db_update_mode(sid,str(c.get('game_mode','classic')),1,q,d)",
"    restart=service_action(sid,'restart')",
"    current=load_server(sid)",
"    return {'ok':True,'id':sid,'bots':'YaPB','quota':q,'difficulty':d,",
"            'bots_enabled':bool(current.get('bots_enabled',0)),",
"            'restart':restart,'warning':restart.get('warning','')}",
"",
""
])
if 'def enable_yapb(' not in s:
    marker='def disable_yapb(sid:int):'
    if marker not in s:
        raise SystemExit('disable_yapb marker missing')
    s=s.replace(marker,enable_fn+marker,1)

start=s.find('def disable_yapb(sid:int):')
end=s.find('\ndef install_zp43(',start)
if start>=0 and end>start:
    old=s[start:end]
    if '_set_yapb_metamod_enabled' not in old:
        new="\n".join([
        "def disable_yapb(sid:int):",
        "    require_root(); c=load_server(sid); cstrike=Path(c['path'])/'cstrike'",
        "    _set_yapb_metamod_enabled(cstrike,False)",
        "    c['bots_enabled']=0; save_server(c)",
        "    db_update_mode(sid,str(c.get('game_mode','classic')),0,int(c.get('bots_quota',9)),int(c.get('bots_difficulty',3)))",
        "    restart=service_action(sid,'restart')",
        "    return {'ok':True,'bots_enabled':False,'restart':restart,'warning':restart.get('warning','')}",
        "",
        ""
        ])
        s=s[:start]+new+s[end:]

if "sp.add_parser('bots-enable')" not in s:
    needle="q=sp.add_parser('bots-install'); q.add_argument('id',type=int); q.add_argument('--quota',type=int,default=9); q.add_argument('--difficulty',type=int,default=3)"
    if needle not in s:
        raise SystemExit('bots-install parser line missing')
    s=s.replace(
        needle,
        needle+"\n    q=sp.add_parser('bots-enable'); q.add_argument('id',type=int); q.add_argument('--quota',type=int); q.add_argument('--difficulty',type=int)",
        1
    )

if "args.cmd=='bots-enable'" not in s:
    needle="elif args.cmd=='bots-install': result=install_yapb(args.id,args.quota,args.difficulty)"
    if needle not in s:
        raise SystemExit('bots-install dispatch line missing')
    s=s.replace(
        needle,
        needle+"\n        elif args.cmd=='bots-enable': result=enable_yapb(args.id,args.quota,args.difficulty)",
        1
    )

compile(s,str(p),'exec')
p.write_text(s,encoding='utf-8')
print('[OK] controller syntax valid:',p)
PY

  chmod 0755 "$CTL"
  PATCHED_CTL=$((PATCHED_CTL+1))
done

if [[ "$PATCHED_CTL" -eq 0 ]]; then
  echo "[WARN] No real Python controller patched. Wrappers were intentionally skipped."
fi

UNIT="hyper-cs16@${SID}.service"
echo
echo "[FINAL] Restarting $UNIT ..."
systemctl daemon-reload >/dev/null 2>&1 || true
systemctl reset-failed "$UNIT" >/dev/null 2>&1 || true
systemctl restart "$UNIT"
sleep 8

if systemctl is-active --quiet "$UNIT"; then
  echo "[OK] $UNIT is active."
else
  echo "[ERROR] Server failed after patch."
  journalctl -u "$UNIT" -n 160 --no-pager -o cat
  exit 30
fi

if grep -Eq '^[[:space:]]*zm_addon_knife\.amxx([[:space:]]|$)' "$PLUGINS"; then
  echo "[OK] zm_addon_knife.amxx is active."
else
  echo "[ERROR] Knife plugin is not active."
  exit 31
fi

echo
echo "================================================================"
echo " [SUCCESS] OLD ZOMBIE CORE FIX v3 applied"
echo "================================================================"
echo "FastDL:"
echo "  http://${PUBLIC_IP}/fastdl/${SID}/maps/zm_2day.bsp"
echo "  BSP v30 verified, SHA256 identical"
echo
echo "Knife:"
echo "  zm_addon_knife.amxx restored/enabled"
echo "  /knife and knife_zb available"
echo
echo "YaPB:"
echo "  bots-config re-enables YaPB"
echo "  bots-enable command added"
echo "  bots-disable supported"
echo
echo "Backup: $BACKUP"
echo
echo "CLIENT NOTE:"
echo "  If a broken HTML file was already saved as the map, delete:"
echo "    cstrike_downloads/maps/zm_2day.bsp"
echo "  then reconnect."
